['ec_zahlung_aktiv']??0)===1):?><option value="ec" <?=$editInvoice['zahlungsart']==='ec'?'selected':''?>>EC</option><?php endif;?></select></label><div class="fields"><label>Kopftext<textarea name="kopftext" maxlength="10000"><?=invoicesH($editInvoice['kopftext']??'')?></textarea></label><label>Fußzeile<textarea name="fusszeile" maxlength="10000"><?=invoicesH($editInvoice['fusszeile']??'')?></textarea></label></div><label>Auftragstext<textarea name="auftragstext" maxlength="10000"><?=invoicesH($editInvoice['auftragstext']??'')?></textarea></label><div class="actions"><button class="button" name="action" value="save_draft">Entwurf speichern</button><button class="button warn" name="action" value="issue" formtarget="_blank" onclick="return confirm('Rechnung verbindlich ausstellen? Der Entwurf wird danach nicht mehr bearbeitbar.');">Rechnung ausstellen</button><a class="button light" href="invoices.php">Schließen</a></div></form></section><?php endif;?>
<div class="grid"><section class="card"><h2>Rechnungen (<?=count($invoices)?>)</h2><?php if(!$invoices):?><p class="hint">Noch keine Rechnungen vorhanden.</p><?php else:foreach($invoices as $invoice):?><article class="row"><strong><?=invoicesH($invoice['rechnungsnummer']?:('Entwurf #'.$invoice['id']))?></strong> · <span class="badge"><?=invoicesH($invoice['status'])?></span><div class="meta"><?=invoicesH($invoice['empfaenger_name'])?> · <?=invoicesH($invoice['auftrag_titel'])?> · <?=invoicesH(date('d.m.Y',strtotime($invoice['sitzung_beginn'])))?></div><div><?=number_format((float)$invoice['brutto'],2,',','.')?> EUR</div><div class="actions"><?php if($invoice['status']==='entwurf'):?><a class="button light" href="invoices.php?edit=<?=(int)$invoice['id']?>">Entwurf öffnen</a><?php else:?><a class="button light" href="invoice-view.php?id=<?=(int)$invoice['id']?>" target="_blank" rel="noopener">Ansehen / drucken</a><?php endif;?><a class="button light" href="invoice-order-summary.php?id=<?=(int)$invoice['auftrag_id']?>">Auftragsübersicht</a><?php if($invoice['status']==='gestellt'):?><form method="post"><input type="hidden" name="csrf_token" value="<?=invoicesH($token)?>"><input type="hidden" name="action" value="mark_paid"><input type="hidden" name="id" value="<?=(int)$invoice['id']?>"><button class="button">Als bezahlt markieren</button></form><?php endif;?></div></article><?php endforeach;endif;?></section>
<section class="card"><h2>Durchgeführte Sitzungen ohne Rechnung (<?=count($billableSessions)?>)</h2><?php if(!$billableSessions):?><p class="hint">Keine offenen Sitzungen zur Abrechnung.</p><?php else:foreach($billableSessions as $session):?><article class="row"><strong><?=invoicesH($session['vorname'].' '.$session['nachname'])?></strong><div class="meta"><?=invoicesH($session['auftrag_titel'])?> · <?=invoicesH(date('d.m.Y H:i',strtotime($session['beginn'])))?> · <?=(int)$session['dauer_minuten']?> Minuten</div><form method="post"><input type="hidden" name="csrf_token" value="<?=invoicesH($token)?>"><input type="hidden" name="action" value="create"><input type="hidden" name="termin_id" value="<?=(int)$session['id']?>"><button class="button">Einzelrechnung erstellen</button></form></article><?php endforeach;endif;?></section></div>
